-- ============================================================
-- UnikTap · вузы Шымкента: описания, история, контакты, соцсети
--
-- ЭТОТ ФАЙЛ СГЕНЕРИРОВАН из supabase/shymkent-info.data.mjs — не правьте руками.
-- Проще всего залить эти данные командой из корня проекта:
--     node supabase/apply-shymkent-info.mjs
-- SQL ниже — запасной путь, если хочется через SQL Editor.
--
-- Дополняет shymkent-universities.sql (программы и цены).
-- Порядок: setup-all.sql → shymkent-universities.sql → этот файл.
--
-- Источники (проверено 24.08.2026):
--   univery.kz   — история, приёмная комиссия, соцсети, общежития
--   univision.kz — численность студентов и преподавателей, адреса
--
-- Чего нет в источниках, того нет и здесь.
--
-- Что стоит проверить руками:
--   • тип вуза у ЮКМА, ЦАИУ и университета Ташенева: univision относит их
--     к международным/национальным, univery — к частным. Скрипт тип НЕ трогает.
--   • военная кафедра проставлена только там, где источник её прямо называет
--     (ЮКУ им. Ауэзова и «Мирас»). У остальных «нет» — значение по умолчанию,
--     а не подтверждённый факт.
--
-- Скрипт безопасно запускать повторно.
-- ============================================================

-- ── 1. Южно-Казахстанский университет имени М. Ауэзова ────────────────────
update public.universities set
  website = 'https://auezov.edu.kz',
  phones = array['+7 (7252) 21-01-41', '+7 (7252) 21-08-94', '+7 (7252) 27-38-52', '+7 (747) 275-75-00'],
  whatsapp = '77472757500',
  socials = '{"instagram":"https://www.instagram.com/auezov_university","facebook":"https://www.facebook.com/auezov.university","youtube":"https://www.youtube.com/@auezovtvfm3799","telegram":"https://t.me/auezov_u"}'::jsonb,
  description_ru = 'Крупнейший многопрофильный университет юга Казахстана и один из ведущих государственных вузов страны. Более 17 тысяч студентов, свыше 1600 преподавателей, 166 программ бакалавриата, 111 магистратуры и 32 докторантуры. Восемь факультетов: инженерии и информационных технологий, строительства и транспорта, естественных наук, гуманитарных наук, экономики и права, аграрный, педагогики и культуры, химических технологий.',
  history_ru = E'Университет основан в 1943 году как институт строительных материалов — первый технический вуз региона, созданный в разгар войны под нужды восстановления промышленности.\n\nЗа следующие десятилетия вуз прошёл несколько преобразований и реорганизаций, расширив профиль от строительных материалов до химических технологий, инженерии, аграрных и гуманитарных направлений.\n\nВ 1998 году получил статус государственного университета и современное название — в честь классика казахской литературы Мухтара Ауэзова.\n\nСегодня это крупный образовательный и научный центр с собственными лабораториями, международными проектами и партнёрствами с предприятиями региона.',
  admission_intro_ru = E'Приём документов: бакалавриат — с 20 июня по 25 августа, магистратура — с 1 июля по 15 августа, докторантура — с 3 июля по 10 августа.\n\nДля бакалавриата нужны: аттестат или диплом (оригинал и копия), копия удостоверения личности, 6 фотографий 3×4, медицинская справка формы 075-У, сертификат ЕНТ, документы на грант при наличии. Подать можно лично или через электронную систему университета.\n\nПри университете работают подготовительные курсы к ЕНТ.',
  has_military_department = true,
  has_dormitory = true,
  dormitory_info_ru = 'Иногородние и иностранные студенты могут получить место в студенческих резиденциях.',
  updated_at = now()
where slug = 'auezov-university';

-- ── 2. Южно-Казахстанская медицинская академия ────────────────────────────
update public.universities set
  website = 'https://skma.edu.kz',
  address_ru = 'г. Шымкент, площадь Аль-Фараби, 1',
  phones = array['+7 (7252) 39-57-57', '+7 (7252) 40-82-22', '+7 (7252) 40-82-08', '+7 (7252) 40-82-29'],
  socials = '{"instagram":"https://www.instagram.com/medacadem_skma","facebook":"https://www.facebook.com/ukma.kz","youtube":"https://www.youtube.com/@skma-edu-kz"}'::jsonb,
  description_ru = 'Медицинский вуз Шымкента: бакалавриат, интернатура, резидентура, магистратура и докторантура по медицине, стоматологии, фармации, сестринскому делу и общественному здравоохранению. Четыре факультета, более 4300 студентов, из них свыше 600 иностранных граждан. Клинико-симуляционный центр, лаборатории и учебные клинические базы. Ректор — Сейтжанова Жанна Серикжановна.',
  history_ru = E'История академии начинается 3 июля 1979 года, когда постановлением Совета Министров Казахской ССР № 247 в Чимкенте открыли филиал Алма-Атинского государственного медицинского института — регион остро нуждался в собственных медицинских кадрах.\n\nВ 1990 году филиал стал самостоятельным вузом — Шымкентским государственным фармацевтическим институтом. В 1994 году получил медицинский статус, в 1997 году — статус Южно-Казахстанской государственной медицинской академии.\n\nВ 2016 году вуз реорганизован в акционерное общество, а с 2018 года носит нынешнее название — АО «Южно-Казахстанская медицинская академия».',
  has_dormitory = true,
  updated_at = now()
where slug = 'skma-shymkent';

-- ── 3. Университет «Мирас» ────────────────────────────────────────────────
update public.universities set
  website = 'https://miras.edu.kz',
  address_ru = 'г. Шымкент, ул. Сапак датка, 2',
  phones = array['+7 (7252) 33-77-77', '+7 775 007-30-00', '+7 702 777-55-33', '+7 771 630-47-36'],
  socials = '{"instagram":"https://www.instagram.com/miras.education","facebook":"https://www.facebook.com/mirasuniversity","telegram":"https://t.me/MirasEducation1997","vk":"https://vk.com/mirasuniversity"}'::jsonb,
  description_ru = 'Частный университет Шымкента с миссией «Доступное образование для качественной жизни». Экономика, право, информационные технологии, педагогика, дизайн и туризм — 23 программы бакалавриата и 9 магистратуры. Обучение на казахском, русском и английском языках. Собственная образовательная платформа Miras.App, бассейн, тренажёрный зал, спортивный комплекс и языковой центр.',
  history_ru = E'Университет основан в мае 1997 года на базе научно-учебного центра МКТУ имени А. Яссави, созданного Министерством образования и науки в августе 1996 года для разработки образовательных технологий по международным стандартам.\n\nК середине 1990-х стало очевидно, что прежняя система гуманитарного и экономического образования не отвечает новой экономической реальности. Так появился частный вуз нового типа — с академической свободой и практико-ориентированным подходом.\n\nКлючевые вехи: 2006 — открытие магистратуры; 2009 — аккредитация Американским советом по аккредитации университетов; 2014–2016 — новый учебный корпус, спортивный комплекс, языковой центр и военная кафедра; 2017 — международная институциональная аккредитация IQAA на пять лет; 2019 — запуск платформы Miras.App; 2020 — бассейн и тренажёрный зал; 2023 — повторная аккредитация IQAA и модернизация 34 образовательных программ.',
  has_military_department = true,
  accreditation_ru = 'Международная институциональная аккредитация IQAA (2017, повторно в 2023 на 5 лет). Специализированная аккредитация образовательных программ с 2018 года.',
  updated_at = now()
where slug = 'miras-university';

-- ── 4. Южно-Казахстанский педагогический университет им. Ө. Жәнібекова ────
update public.universities set
  website = 'https://zhanibekov.edu.kz',
  address_ru = 'г. Шымкент, 160012, ул. А. Байтурсынова, 13',
  phones = array['+7 (7252) 30-14-59', '+7 (7252) 21-41-01', '+7 708 438-65-61', '+7 708 438-65-62'],
  socials = '{"instagram":"https://www.instagram.com/zhanibekovuniversity","telegram":"https://t.me/zhanibekovuniversity"}'::jsonb,
  description_ru = 'Один из старейших педагогических вузов страны. Шесть факультетов: естествознания, филологический, физико-математический, истории и педагогики, искусства и образования, физической культуры и спорта. 55 программ бакалавриата, 24 магистратуры и 15 докторантуры. Кампус в центре Шымкента: учебные корпуса, библиотеки, спортивные залы, современные общежития. Ректор — Гульжан Даулетбековна Сугирбаева.',
  history_ru = E'19 марта 1937 года постановлением Совета Народных Комиссаров Казахской ССР в Шымкенте открыли первый учительский институт. К середине века он стал главным центром подготовки педагогов для всего юга республики.\n\nВ 1954 году институт получил статус педагогического. В 1987 году, к 50-летию, ему присвоили имя Мухтара Ауэзова.\n\nС начала 1990-х вуз несколько раз реорганизовывали, он входил в состав других университетов, включая Международный казахско-турецкий. В 2011 году был восстановлен как самостоятельный Южно-Казахстанский государственный педагогический институт.\n\n17 ноября 2017 года получил статус университета, в 2018 году преобразован в некоммерческое акционерное общество. В 2019 году построены студенческий дом и новое общежитие.\n\n3 октября 2023 года приказом Министерства науки и высшего образования № 512 университету присвоено имя государственного и общественного деятеля Узбекали Жанибекова.',
  admission_intro_ru = E'Приём документов: бакалавриат — с 20 июня по 25 августа, магистратура — с 10 июля по 30 августа, докторантура — с 3 июля по 30 августа.\n\nНужны: онлайн-регистрация, удостоверение личности, аттестат с приложением, 2 фотографии, медицинская справка формы 075-У и результаты ЕНТ.\n\nПриёмная комиссия: ул. Байтурсынова, главный корпус, 1 этаж.',
  working_hours_ru = 'Приёмная комиссия: 09:00–18:00, в период приёма — без выходных',
  has_dormitory = true,
  dormitory_info_ru = 'Студенческий дом на 350 мест, построен в 2019 году, и общежитие на 200 мест уровня четырёхзвёздочного отеля.',
  updated_at = now()
where slug = 'zhanibekov-university';

