  socials = '{"instagram":"https://www.instagram.com/tashenev.university","facebook":"https://www.facebook.com/tashenovu","youtube":"https://www.youtube.com/@Tashenev"}'::jsonb,
  description_ru = 'В главном корпусе — четыре факультета и девять кафедр, Центр инновационных исследований, лаборатории химии, биологии и физики, компьютерные классы и библиотека с фондом свыше 340 тысяч образовательных ресурсов. 60 программ бакалавриата и 9 магистратуры, более девяти тысяч студентов. Партнёрства с 15 казахстанскими и 12 зарубежными университетами, среди них Ataturk University и РАНХиГС.',
  history_ru = E'История вуза начинается в 1998 году с университета «Сырдария» в городе Жетысай — его открыли, чтобы дать доступное высшее образование молодёжи из отдалённых районов юга страны.\n\nВ 2005 году на открытие нового корпуса приезжал Президент. В 2010 году создан Инновационный научно-исследовательский центр, в 2016 году вуз прошёл институциональную аккредитацию.\n\nВ 2022 году университет переехал в Шымкент и был переименован в честь Жумабека Ташенева — государственного деятеля, отстоявшего территориальную целостность Казахстана.',
  admission_intro_ru = E'Приёмная комиссия начинает работу 20 июня. Нужны: документ об образовании (оригинал), 8 фотографий 3×4, копия удостоверения личности, сертификат ЕНТ при наличии, медицинская справка формы 075-У с флюорографией.\n\nБакалавриат доступен в трёх вариантах: 4 года очно, 3 года по ускоренной программе, 2 года для выпускников колледжей.',
  has_dormitory = true,
  dormitory_info_ru = 'Два общежития на 220 мест. Комнаты с мебелью и бытовой техникой, на территории кампуса — спортивные площадки и творческие студии.',
  accreditation_ru = 'Институциональная аккредитация пройдена в 2016 году.',
  updated_at = now()
where slug = 'tashenev-university';

