  socials = '{"instagram":"https://www.instagram.com/oaiu.edu.kz","youtube":"https://www.youtube.com/@oaiu.education"}'::jsonb,
  description_ru = 'Четыре учебных корпуса общей площадью свыше 32 тысяч квадратных метров, общежитие, спортивные залы, бассейн, тренажёрный зал и загородный учебно-тренировочный лагерь. Свыше 11 тысяч студентов, более 400 преподавателей, остепенённость выше 50%. Совместные программы с вузами Узбекистана и Кыргызстана. Среди выпускников и студентов — бронзовый призёр Олимпийских игр в Токио Серик Бибосынов.',
  history_ru = E'Университет создан 24 февраля 2021 года объединением двух учебных заведений — Международного гуманитарно-технического университета и Института имени М. Сапарбаева. Слияние прошло в рамках Послания Президента о повышении качества высшего образования.\n\n2 марта 2021 года вуз получил государственную лицензию на образовательную деятельность в области высшего и послевузовского образования.',
  admission_intro_ru = E'Приём заявлений начинается 20 июня, бакалавриат (очная форма) — до 25 августа, магистратура — с 1 июля по 15 августа.\n\nНужны: заявление, оригинал аттестата или диплома, 6 фотографий 3×4, электронный сертификат ЕНТ, медицинская справка формы 075-У, копия удостоверения личности, приписное свидетельство для юношей.\n\nСкидки: детям-сиротам от 20% до 100%, студентам из многодетных семей 15%, 10% при полной оплате за год, отдельные условия для абитуриентов с высокими баллами ЕНТ.',
  has_dormitory = true,
  dormitory_info_ru = 'Общежитие на 270 мест.',
