-- ── Проверка ─────────────────────────────────────────────────────────
select
  u.short_name                                              as вуз,
  case when u.description_ru <> '' then '✓' else '—' end    as описание,
  case when u.history_ru <> ''     then '✓' else '—' end    as история,
  (select count(*) from jsonb_object_keys(u.socials))       as соцсетей,
  array_length(u.phones, 1)                                 as телефонов,
  case when u.has_dormitory then '✓' else '—' end           as общежитие,
  case when u.has_military_department then '✓' else '—' end as воен_кафедра
from public.universities u
where u.city_id = (select id from public.cities where slug = 'shymkent')
order by u.sort_order;
